#!/usr/bin/env bash
set -euo pipefail
PIXSEAL="${PIXSEAL:?set PIXSEAL to the built pixseal executable}"
ACQUISITION_DIR="${V4_PHONE_ACQUISITION_DIR:-v4-phone private/build38-acquired}"
OUTPUT_DIR="${V4_PHONE_BUILD78_DIAGNOSTIC_DIR:-v4-phone private/build78-diagnostics}"
KEY="${V4_PHONE_KEY:-PixSeal-v4-TestKey-2026}"
CANONICAL_WIDTH="${V4_PHONE_CANONICAL_WIDTH:-1632}"
CANONICAL_HEIGHT="${V4_PHONE_CANONICAL_HEIGHT:-1632}"
MESSAGE_A="${V4_PHONE_MESSAGE_A:-v4-b38-phone-a}"
MESSAGE_B="${V4_PHONE_MESSAGE_B:-v4-b38-phone-b}"
PHONE_TIMEOUT="${V4_PHONE_BUILD78_TIMEOUT:-86400}"
[[ -x "$PIXSEAL" ]] || { echo "error: PIXSEAL is not executable: $PIXSEAL" >&2; exit 1; }
command -v timeout >/dev/null 2>&1 || { echo "error: GNU timeout is required" >&2; exit 1; }
[[ -d "$ACQUISITION_DIR" ]] || { echo "error: phone acquisition directory not found: $ACQUISITION_DIR" >&2; exit 1; }
[[ "$PHONE_TIMEOUT" =~ ^[0-9]+$ ]] || { echo "error: V4_PHONE_BUILD78_TIMEOUT must be an integer number of seconds" >&2; exit 1; }
specs=(
 "phone-control-front.jpg|control|control|-"
 "phone-control-mild.jpg|control|control|-"
 "phone-control-angle.jpg|control|control|-"
 "phone-a-front.jpg|A|required-build43|$MESSAGE_A"
 "phone-a-mild.jpg|A|required-any|$MESSAGE_A"
 "phone-a-angle.jpg|A|required-direct|$MESSAGE_A"
 "phone-b-front.jpg|B|required-direct|$MESSAGE_B"
 "phone-b-mild.jpg|B|required-build78|$MESSAGE_B"
 "phone-b-angle.jpg|B|required-reject|$MESSAGE_B"
)
for spec in "${specs[@]}"; do IFS='|' read -r file _ <<< "$spec"; [[ -f "$ACQUISITION_DIR/$file" ]] || { echo "error: missing required acquisition: $ACQUISITION_DIR/$file" >&2; exit 1; }; done
output_parent="$(dirname "$OUTPUT_DIR")"; output_base="$(basename "$OUTPUT_DIR")"; mkdir -p "$output_parent"
stage_dir="$(mktemp -d "$output_parent/.${output_base}.build78.XXXXXX")"; published=false
cleanup_stage(){ if [[ "$published" != true && -d "$stage_dir" ]]; then rm -rf "$stage_dir"; fi; }; trap cleanup_stage EXIT
mkdir -p "$stage_dir/logs"
tsv="$stage_dir/build78-phone-continuation4-profile.tsv"; md="$stage_dir/build78-phone-continuation4-profile.md"
final_tsv="$OUTPUT_DIR/build78-phone-continuation4-profile.tsv"; final_md="$OUTPUT_DIR/build78-phone-continuation4-profile.md"
printf 'image\tclass\trole\tbuild64_evals\tbuild64_bank\tbuild64_qualified\tbuild64_decode\tbuild64_frames\tbuild64_authenticated\tbuild68_physical_decode\tbuild68_speculative\tbuild75_attempted\tbuild76_attempted\tbuild78_attempted\tgen4_workers\tgen4_tasks\tgen4_wall_ms\tgen4_worker_ms\tcontinue4_calls\tcontinue4_outputs\tcontinue4_evals\tcontinue4_worker_ms\tinput_states\tprobe_attempts\tlimit_rejected\thomography_rejected\tscore_evals\tinvalid_scores\tnon_improving\timproving_probes\taccepted_states\tduplicate_accepted\tpasses\tscore_worker_ms\tprepare_worker_ms\tmin_ms\tmedian_ms\tmax_ms\tmin_evals\tmax_evals\tmin_accepted\tmax_accepted\tdominant_call\tdominant_gen4_task\tdominant_pair_rank\tdominant_evals\tdominant_accepted\tdominant_passes\tdominant_ms\tdominant_score_ms\tdominant_probes\tdominant_limit_rejected\tdominant_homography_rejected\tdominant_invalid_scores\tdominant_non_improving\tdominant_improving_probes\tdominant_duplicate_accepted\thmac\tpayload_match\ttelemetry_equivalent\tqualification\texit_code\telapsed_ms\tgeometry_ms\tfreeze_ms\tprefix1_ms\tgen2_ms\tgen3_ms\n' > "$tsv"
extract_re(){ local pattern="$1" file="$2" default_value="${3:-}" value; value="$(sed -nE "s/$pattern/\\1/p" "$file" | head -n1)"; [[ -n "$value" ]] && printf '%s' "$value" || printf '%s' "$default_value"; }
for spec in "${specs[@]}"; do
 IFS='|' read -r file class role expected_payload <<< "$spec"; input="$ACQUISITION_DIR/$file"; stem="${file%.*}"; log="$stage_dir/logs/$stem.stderr.txt"; payload_file="$stage_dir/logs/$stem.payload.bin"
 start_ns="$(date +%s%N)"; set +e; timeout --foreground "${PHONE_TIMEOUT}s" "$PIXSEAL" v4-extract-phone -in "$input" -key "$KEY" -width "$CANONICAL_WIDTH" -height "$CANONICAL_HEIGHT" -raw >"$payload_file" 2>"$log"; rc=$?; set -e; end_ns="$(date +%s%N)"; elapsed_ms=$(( (end_ns-start_ns)/1000000 ))
 hmac="$(extract_re 'hmac: authenticated=([^ ]+).*' "$log" false)"; b43_attempted=false; b43_auth=false; if grep -q '^build43-geometry:' "$log"; then b43_attempted=true; b43_auth="$(extract_re 'build43-geometry: .* authenticated=([^ ]+).*' "$log" false)"; fi
 b64_attempted=false;b64_evals=0;b64_bank=0;b64_qualified=0;b64_decode=0;b64_frames=0;b64_auth=false
 if grep -q '^build64-recovery:' "$log"; then b64_attempted=true; b64_evals="$(extract_re 'build64-recovery: .* geometry-evals=([0-9]+).*' "$log" 0)"; b64_bank="$(extract_re 'build64-recovery: .* bank=([0-9]+).*' "$log" 0)"; b64_qualified="$(extract_re 'build64-recovery: .* qualified=([0-9]+).*' "$log" 0)"; b64_decode="$(extract_re 'build64-recovery: .* decode-candidates=([0-9]+).*' "$log" 0)"; b64_frames="$(extract_re 'build64-recovery: .* list-frames=([0-9]+).*' "$log" 0)"; b64_auth="$(extract_re 'build64-recovery: .* authenticated=([^ ]+).*' "$log" false)"; fi
 b65=false; grep -q '^build65-parallel:' "$log" && b65=true; b66=false;b66_workers=0; if grep -q '^build66-decode-parallel:' "$log"; then b66=true;b66_workers="$(extract_re 'build66-decode-parallel: .* workers=([0-9]+).*' "$log" 0)"; fi
 b68=false;b68_physical=0;b68_spec=0;geometry_ms=0;if grep -q '^build68-plane-reuse:' "$log";then b68=true;b68_physical="$(extract_re 'build68-plane-reuse: .* physical-decode-candidates=([0-9]+).*' "$log" 0)";b68_spec="$(extract_re 'build68-plane-reuse: .* speculative-candidates=([0-9]+).*' "$log" 0)";geometry_ms="$(extract_re 'build68-plane-reuse: .* geometry-ms=([0-9]+).*' "$log" 0)";fi
 b73=false;grep -q '^build73-gen3-parallel:' "$log"&&b73=true;b75=false;grep -q '^build75-basin-parallel:' "$log"&&b75=true;b76=false;grep -q '^build76-gen2-parallel:' "$log"&&b76=true;b78=false;grep -q '^build78-continuation4-profile:' "$log"&&b78=true
 gen4_workers=0;gen4_tasks=0;gen4_wall=0;gen4_worker=0;freeze=0;prefix1=0;gen2=0;gen3=0
 if [[ "$b76" == true ]]; then gen4_workers="$(extract_re 'build76-gen2-parallel: .* gen4-workers=([0-9]+).*' "$log" 0)";gen4_tasks="$(extract_re 'build76-gen2-parallel: .* gen4-tasks=([0-9]+).*' "$log" 0)";gen4_wall="$(extract_re 'build76-gen2-parallel: .* gen4-wall-ms=([0-9]+).*' "$log" 0)";gen4_worker="$(extract_re 'build76-gen2-parallel: .* gen4-worker-ms=([0-9]+).*' "$log" 0)";freeze="$(extract_re 'build76-gen2-parallel: .* freeze-ms=([0-9]+).*' "$log" 0)";prefix1="$(extract_re 'build76-gen2-parallel: .* prefix1-wall-ms=([0-9]+).*' "$log" 0)";gen2="$(extract_re 'build76-gen2-parallel: .* gen2-wall-ms=([0-9]+).*' "$log" 0)";gen3="$(extract_re 'build76-gen2-parallel: .* gen3-wall-ms=([0-9]+).*' "$log" 0)";fi
 cont_calls=0;cont_out=0;cont_e=0;cont_ms=0;input_states=0;probes=0;limit_rej=0;hom_rej=0;score_e=0;invalid=0;nonimp=0;impprobes=0;accepted=0;dups=0;passes=0;score_ms=0;prep_ms=0;min_ms=0;median_ms=0;max_ms=0;min_e=0;max_e=0;min_acc=0;max_acc=0;dom_call=0;dom_task=0;dom_pair=0;dom_e=0;dom_acc=0;dom_passes=0;dom_ms=0;dom_score_ms=0;dom_probes=0;dom_limit=0;dom_hom=0;dom_invalid=0;dom_nonimp=0;dom_impprobes=0;dom_dups=0
 if [[ "$b78" == true ]]; then
   cont_calls="$(extract_re 'build78-continuation4-profile: .* continue4-calls=([0-9]+).*' "$log" 0)";cont_out="$(extract_re 'build78-continuation4-profile: .* continue4-outputs=([0-9]+).*' "$log" 0)";cont_e="$(extract_re 'build78-continuation4-profile: .* continue4-evals=([0-9]+).*' "$log" 0)";cont_ms="$(extract_re 'build78-continuation4-profile: .* continue4-worker-ms=([0-9]+).*' "$log" 0)";input_states="$(extract_re 'build78-continuation4-profile: .* input-states=([0-9]+).*' "$log" 0)";probes="$(extract_re 'build78-continuation4-profile: .* probe-attempts=([0-9]+).*' "$log" 0)";limit_rej="$(extract_re 'build78-continuation4-profile: .* limit-rejected=([0-9]+).*' "$log" 0)";hom_rej="$(extract_re 'build78-continuation4-profile: .* homography-rejected=([0-9]+).*' "$log" 0)";score_e="$(extract_re 'build78-continuation4-profile: .* score-evals=([0-9]+).*' "$log" 0)";invalid="$(extract_re 'build78-continuation4-profile: .* invalid-scores=([0-9]+).*' "$log" 0)";nonimp="$(extract_re 'build78-continuation4-profile: .* non-improving=([0-9]+).*' "$log" 0)";impprobes="$(extract_re 'build78-continuation4-profile: .* improving-probes=([0-9]+).*' "$log" 0)";accepted="$(extract_re 'build78-continuation4-profile: .* accepted-states=([0-9]+).*' "$log" 0)";dups="$(extract_re 'build78-continuation4-profile: .* duplicate-accepted=([0-9]+).*' "$log" 0)";passes="$(extract_re 'build78-continuation4-profile: .* passes=([0-9]+).*' "$log" 0)";score_ms="$(extract_re 'build78-continuation4-profile: .* score-worker-ms=([0-9]+).*' "$log" 0)";prep_ms="$(extract_re 'build78-continuation4-profile: .* prepare-worker-ms=([0-9]+).*' "$log" 0)";min_ms="$(extract_re 'build78-continuation4-profile: .* min-ms=([0-9]+).*' "$log" 0)";median_ms="$(extract_re 'build78-continuation4-profile: .* median-ms=([0-9]+).*' "$log" 0)";max_ms="$(extract_re 'build78-continuation4-profile: .* max-ms=([0-9]+).*' "$log" 0)";min_e="$(extract_re 'build78-continuation4-profile: .* min-evals=([0-9]+).*' "$log" 0)";max_e="$(extract_re 'build78-continuation4-profile: .* max-evals=([0-9]+).*' "$log" 0)";min_acc="$(extract_re 'build78-continuation4-profile: .* min-accepted=([0-9]+).*' "$log" 0)";max_acc="$(extract_re 'build78-continuation4-profile: .* max-accepted=([0-9]+).*' "$log" 0)";dom_call="$(extract_re 'build78-continuation4-profile: .* dominant-call=([0-9]+).*' "$log" 0)";dom_task="$(extract_re 'build78-continuation4-profile: .* dominant-call-gen4-task=([0-9]+).*' "$log" 0)";dom_pair="$(extract_re 'build78-continuation4-profile: .* dominant-pair-rank=([0-9]+).*' "$log" 0)";dom_e="$(extract_re 'build78-continuation4-profile: .* dominant-evals=([0-9]+).*' "$log" 0)";dom_acc="$(extract_re 'build78-continuation4-profile: .* dominant-accepted=([0-9]+).*' "$log" 0)";dom_passes="$(extract_re 'build78-continuation4-profile: .* dominant-passes=([0-9]+).*' "$log" 0)";dom_ms="$(extract_re 'build78-continuation4-profile: .* dominant-ms=([0-9]+).*' "$log" 0)";dom_score_ms="$(extract_re 'build78-continuation4-profile: .* dominant-score-ms=([0-9]+).*' "$log" 0)";dom_probes="$(extract_re 'build78-continuation4-profile: .* dominant-probes=([0-9]+).*' "$log" 0)";dom_limit="$(extract_re 'build78-continuation4-profile: .* dominant-limit-rejected=([0-9]+).*' "$log" 0)";dom_hom="$(extract_re 'build78-continuation4-profile: .* dominant-homography-rejected=([0-9]+).*' "$log" 0)";dom_invalid="$(extract_re 'build78-continuation4-profile: .* dominant-invalid-scores=([0-9]+).*' "$log" 0)";dom_nonimp="$(extract_re 'build78-continuation4-profile: .* dominant-non-improving=([0-9]+).*' "$log" 0)";dom_impprobes="$(extract_re 'build78-continuation4-profile: .* dominant-improving-probes=([0-9]+).*' "$log" 0)";dom_dups="$(extract_re 'build78-continuation4-profile: .* dominant-duplicate-accepted=([0-9]+).*' "$log" 0)"
 fi
 case "$file" in phone-control-front.jpg) exp_evals=18021;exp_bank=26;exp_qual=0;exp_decode=0;exp_frames=0;; phone-control-mild.jpg) exp_evals=117609;exp_bank=810;exp_qual=6;exp_decode=6;exp_frames=18432;; phone-control-angle.jpg) exp_evals=21203;exp_bank=11;exp_qual=0;exp_decode=0;exp_frames=0;; phone-b-mild.jpg) exp_evals=79259;exp_bank=937;exp_qual=935;exp_decode=691;exp_frames=2120047;; phone-b-angle.jpg) exp_evals=334857;exp_bank=6198;exp_qual=0;exp_decode=0;exp_frames=0;; *) exp_evals=0;exp_bank=0;exp_qual=0;exp_decode=0;exp_frames=0;; esac
 telemetry=true
 if [[ "$exp_evals" -gt 0 ]];then [[ "$b64_attempted" == true && "$b64_evals" -eq "$exp_evals" && "$b64_bank" -eq "$exp_bank" && "$b64_qualified" -eq "$exp_qual" && "$b64_decode" -eq "$exp_decode" && "$b64_frames" -eq "$exp_frames" && "$b65" == true && "$b66" == true && "$b68" == true && "$b73" == true && "$b75" == true && "$b76" == true && "$b78" == true && "$gen4_tasks" -gt 0 && "$gen4_workers" -gt 0 && "$cont_calls" -eq "$input_states" && "$cont_e" -eq "$score_e" && "$cont_out" -eq "$accepted" && "$probes" -ge "$score_e" ]]||telemetry=false; if [[ "$exp_qual" -gt 0 ]];then [[ "$b66_workers" -gt 0 && "$b68_physical" -ge "$b64_decode" && "$b68_spec" -eq $((b68_physical-b64_decode)) ]]||telemetry=false; [[ "$b64_auth" == false || "$b68_spec" -lt "$b66_workers" ]]||telemetry=false;else [[ "$b66_workers" -eq 0 && "$b68_physical" -eq 0 && "$b68_spec" -eq 0 ]]||telemetry=false;fi; else [[ "$b64_attempted" == false && "$b73" == false && "$b75" == false && "$b76" == false && "$b78" == false ]]||telemetry=false;fi
 payload_match='-';qualification=INFO
 if [[ "$role" == control ]];then [[ $rc -ne 0 && "$hmac" == false && "$b64_auth" == false ]]&&qualification=PASS||qualification=FAIL;else if [[ $rc -eq 0 ]];then actual="$(cat "$payload_file")";[[ "$actual" == "$expected_payload" ]]&&payload_match=true||payload_match=false;else payload_match=false;fi;case "$role" in required-direct) [[ $rc -eq 0 && "$payload_match" == true && "$hmac" == true && "$b43_attempted" == false && "$b64_attempted" == false ]]&&qualification=PASS||qualification=FAIL;; required-build43) [[ $rc -eq 0 && "$payload_match" == true && "$hmac" == true && "$b43_attempted" == true && "$b43_auth" == true && "$b64_attempted" == false ]]&&qualification=PASS||qualification=FAIL;; required-any) [[ $rc -eq 0 && "$payload_match" == true && "$hmac" == true && "$b64_attempted" == false ]]&&qualification=PASS||qualification=FAIL;; required-build78) [[ $rc -eq 0 && "$payload_match" == true && "$hmac" == true && "$b64_auth" == true && "$b78" == true ]]&&qualification=PASS||qualification=FAIL;; required-reject) [[ $rc -ne 0 && "$hmac" == false && "$b64_auth" == false && "$b78" == true ]]&&qualification=PASS||qualification=FAIL;; esac;fi
 [[ "$telemetry" == true ]]||qualification=FAIL
 printf '%s\t%s\t%s\t%d\t%d\t%d\t%d\t%d\t%s\t%d\t%d\t%s\t%s\t%s\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%s\t%s\t%s\t%s\t%d\t%d\t%d\t%d\t%d\t%d\t%d\n' "$file" "$class" "$role" "$b64_evals" "$b64_bank" "$b64_qualified" "$b64_decode" "$b64_frames" "$b64_auth" "$b68_physical" "$b68_spec" "$b75" "$b76" "$b78" "$gen4_workers" "$gen4_tasks" "$gen4_wall" "$gen4_worker" "$cont_calls" "$cont_out" "$cont_e" "$cont_ms" "$input_states" "$probes" "$limit_rej" "$hom_rej" "$score_e" "$invalid" "$nonimp" "$impprobes" "$accepted" "$dups" "$passes" "$score_ms" "$prep_ms" "$min_ms" "$median_ms" "$max_ms" "$min_e" "$max_e" "$min_acc" "$max_acc" "$dom_call" "$dom_task" "$dom_pair" "$dom_e" "$dom_acc" "$dom_passes" "$dom_ms" "$dom_score_ms" "$dom_probes" "$dom_limit" "$dom_hom" "$dom_invalid" "$dom_nonimp" "$dom_impprobes" "$dom_dups" "$hmac" "$payload_match" "$telemetry" "$qualification" "$rc" "$elapsed_ms" "$geometry_ms" "$freeze" "$prefix1" "$gen2" "$gen3" >> "$tsv"
done
{
 echo '# PixSeal Build78 continuation4 internal profile'; echo
 echo 'Build78 is observability-only over the qualified Build76 baseline. It preserves the exact Build76 bank/order and scheduler while instrumenting the existing continuation4 coordinate-descent loop. Fine-grained timing overhead makes Build78 non-promotable.'; echo
 echo '| image | role | evals | bank | qual | decode | frames | cont calls | probes | score evals | accepted | non-improving | score ms | prep ms | dom evals | dom accepted | HMAC | telemetry eq | elapsed | geometry | gate |'
 echo '|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|'
 tail -n +2 "$tsv" | awk -F '\t' '{printf "| %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s |\n",$1,$3,$4,$5,$6,$7,$8,$19,$24,$27,$31,$29,$34,$35,$46,$47,$58,$60,$63,$64,$61}'
 echo; echo 'Correctness is authoritative. Build76 remains the qualified baseline; Build78 timing exists only to characterize continuation4 internals.'
} > "$md"
rm -f "$stage_dir/logs/"*.payload.bin
pass_count="$(awk -F '\t' 'NR>1&&$61=="PASS"{n++}END{print n+0}' "$tsv")";control_passes="$(awk -F '\t' 'NR>1&&$3=="control"&&$61=="PASS"{n++}END{print n+0}' "$tsv")";a_front_pass="$(awk -F '\t' 'NR>1&&$1=="phone-a-front.jpg"&&$61=="PASS"{n++}END{print n+0}' "$tsv")";a_mild_pass="$(awk -F '\t' 'NR>1&&$1=="phone-a-mild.jpg"&&$61=="PASS"{n++}END{print n+0}' "$tsv")";a_angle_pass="$(awk -F '\t' 'NR>1&&$1=="phone-a-angle.jpg"&&$61=="PASS"{n++}END{print n+0}' "$tsv")";b_front_pass="$(awk -F '\t' 'NR>1&&$1=="phone-b-front.jpg"&&$61=="PASS"{n++}END{print n+0}' "$tsv")";b_mild_pass="$(awk -F '\t' 'NR>1&&$1=="phone-b-mild.jpg"&&$61=="PASS"{n++}END{print n+0}' "$tsv")";b_angle_pass="$(awk -F '\t' 'NR>1&&$1=="phone-b-angle.jpg"&&$61=="PASS"{n++}END{print n+0}' "$tsv")"
echo "Build78 staged result: controls=${control_passes}/3 A/front=${a_front_pass}/1 A/mild=${a_mild_pass}/1 A/angle=${a_angle_pass}/1 B/front=${b_front_pass}/1 B/mild=${b_mild_pass}/1 B/angle-reject=${b_angle_pass}/1"
if ((pass_count!=9||control_passes!=3||a_front_pass!=1||a_mild_pass!=1||a_angle_pass!=1||b_front_pass!=1||b_mild_pass!=1||b_angle_pass!=1));then echo 'error: Build78 semantic-equivalence physical gate not met' >&2;exit 1;fi
mkdir -p "$OUTPUT_DIR"; rm -rf "$OUTPUT_DIR/logs"; mv "$stage_dir/logs" "$OUTPUT_DIR/logs"; mv "$tsv" "$final_tsv"; mv "$md" "$final_md"; rmdir "$stage_dir"; published=true
echo 'Build78 continuation4 profile written to:'; echo "  $final_tsv"; echo "  $final_md"; echo 'Build78 semantic-equivalence physical gate: PASS'
